const updatePreviewHead = `-- name: UpdatePreviewHead :exec
UPDATE previews
SET title = ?, author = ?, html_url = ?, head_branch = ?, head_sha = ?, pr_updated_at = ?, updated_at = ?
WHERE id = +?
`

type UpdatePreviewHeadParams struct {
	Title       string
	Author      string
	HtmlUrl     string
	HeadBranch  string
	HeadSha     string
	PrUpdatedAt time.Time
	UpdatedAt   time.Time
	ID          int64
}

// Records a newer event's pull request: title, head and its updated_at.
func (q *Queries) UpdatePreviewHead(ctx context.Context, arg UpdatePreviewHeadParams) error {
	_, err := q.db.ExecContext(ctx, updatePreviewHead,
		arg.Title,
		arg.Author,
		arg.HtmlUrl,
		arg.HeadBranch,
		arg.HeadSha,
		arg.PrUpdatedAt,
		arg.UpdatedAt,
		arg.ID,
	)
	return err
}

const upsertPreviewSettings = `-- name: UpsertPreviewSettings :exec
INSERT INTO preview_settings (project_id, base_environment_id, max_previews, copy_variables, allow_forks, updated_by, updated_at)
VALUES (?, ?, ?, ?, ?, ?, ?)
ON CONFLICT (project_id) DO UPDATE SET
    base_environment_id = excluded.base_environment_id, max_previews = excluded.max_previews,
    copy_variables = excluded.copy_variables, allow_forks = excluded.allow_forks,
    updated_by = excluded.updated_by, updated_at = excluded.updated_at
`

type UpsertPreviewSettingsParams struct {
	ProjectID         int64
	BaseEnvironmentID int64
	MaxPreviews       int64
	CopyVariables     string
	AllowForks        bool
	UpdatedBy         string
	UpdatedAt         time.Time
}

func (q *Queries) UpsertPreviewSettings(ctx context.Context, arg UpsertPreviewSettingsParams) error {
	_, err := q.db.ExecContext(ctx, upsertPreviewSettings,
		arg.ProjectID,
		arg.BaseEnvironmentID,
		arg.MaxPreviews,
		arg.CopyVariables,
		arg.AllowForks,
		arg.UpdatedBy,
		arg.UpdatedAt,
	)
	return err
}
